<?php
namespace LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Controllers;
use Illuminate\Routing\Controller;
use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\Incident; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\DeliveryLog; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\HealthService; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\ReadinessService; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\SettingStore;
class OverviewController extends Controller { public function __invoke(SettingStore $settings, ReadinessService $readiness, HealthService $health) { $checks = $readiness->checks(); return view('iapm::overview', ['readiness' => $checks, 'health' => $health->checks(), 'setupComplete' => collect($checks)->where('group','setup')->every(fn($c)=>$c['ok']), 'counts' => Incident::query()->selectRaw('state, count(*) total')->groupBy('state')->pluck('total', 'state'), 'incidents' => Incident::latest('last_seen_at')->paginate(25), 'metrics' => ['active_critical' => Incident::where('state','active')->where('severity','critical')->count(), 'active_warning' => Incident::where('state','active')->where('severity','warning')->count(), 'failed_deliveries' => DeliveryLog::whereIn('status',['failed','failed_configuration'])->where('created_at','>=',now()->subDay())->count(), 'missing_policies' => Incident::where('suppression_reason','no_policy')->where('state','!=','recovered')->count(), 'recovered_24h' => Incident::where('state','recovered')->where('recovered_at','>=',now()->subDay())->count(), 'awaiting_escalation' => Incident::where('state','active')->whereHas('policy.actions',fn($q)=>$q->where('phase','escalation')->where('enabled',true))->count(), 'dry_run' => (bool)$settings->get('dry_run',true)]]); } }
